+export function diffLines(a: string[], b: string[]): DiffOp[] {
+  const m = a.length, n = b.length;
+  const lcs = lcsLengths(a, b);
+  const ops: DiffOp[] = [];
+  let i = 0, j = 0;
+  while (i < m || j < n) {
+    if (i < m && j < n && a[i] === b[j]) {
